import pandas as pd

# File paths for source CSVs
source_files = [
    "autopipeline-benchmarks/github-pipelines/intermediate_space/length6_30/training_0.csv",
    "autopipeline-benchmarks/github-pipelines/intermediate_space/length6_30/training_1.csv",
    "autopipeline-benchmarks/github-pipelines/intermediate_space/length6_30/training_2.csv",
    "autopipeline-benchmarks/github-pipelines/intermediate_space/length6_30/training_3.csv",
    "autopipeline-benchmarks/github-pipelines/intermediate_space/length6_30/training_4.csv",
    "autopipeline-benchmarks/github-pipelines/intermediate_space/length6_30/training_5.csv",
    "autopipeline-benchmarks/github-pipelines/intermediate_space/length6_30/training_6.csv",
    "autopipeline-benchmarks/github-pipelines/intermediate_space/length6_30/training_7.csv",
]

dfs = []
for file in source_files:
    # Read CSV with index_col=0 to ignore the first index column (which is not data)
    df = pd.read_csv(file, index_col=0)
    dfs.append(df)

# Union all source tables (concatenate)
df_all = pd.concat(dfs, ignore_index=True)

# Ensure columns are in the target schema order and types:
# Target schema: ['created': string, 'screenname': string, 'followers': integer, 'favourites': integer, 'text': string]

# Convert 'created' to string (it may contain timezone info in some sources, keep as is)
df_all['created'] = df_all['created'].astype(str)

# Convert 'screenname' to string
df_all['screenname'] = df_all['screenname'].astype(str)

# Convert 'followers' and 'favourites' to integer (if floats appear, convert safely)
df_all['followers'] = pd.to_numeric(df_all['followers'], errors='coerce').fillna(0).astype(int)
df_all['favourites'] = pd.to_numeric(df_all['favourites'], errors='coerce').fillna(0).astype(int)

# Convert 'text' to string (some are bytes literals, decode if needed)
def decode_text(val):
    if isinstance(val, bytes):
        try:
            return val.decode('utf-8', errors='replace')
        except Exception:
            return str(val)
    elif isinstance(val, str):
        # Sometimes text is like b'...' string, remove leading b' and trailing ' if present
        if val.startswith("b'") or val.startswith('b"'):
            try:
                # Evaluate literal bytes string safely
                return eval(val).decode('utf-8', errors='replace')
            except Exception:
                return val
        else:
            return val
    else:
        return str(val)

df_all['text'] = df_all['text'].apply(decode_text)

# Reorder columns to target schema
df_all = df_all[['created', 'screenname', 'followers', 'favourites', 'text']]

# Write to target CSV file without index
df_all.to_csv("autopipeline-benchmarks/github-pipelines/length6_30/target_multisource.csv", index=False)
